  { pfad: "/grossspeicher", prio: 0.8, freq: "monthly" },
  { pfad: "/prozess", prio: 0.7, freq: "monthly" },
  // Zielgruppen
  { pfad: "/flaeche-verpachten", prio: 0.9, freq: "monthly" },
  { pfad: "/landwirte", prio: 0.8, freq: "monthly" },
  { pfad: "/investoren", prio: 0.9, freq: "monthly" },
