/**
 * Öffentliche Exposés der Projektbörse aus dem Plattform-Backend
 * (src/lib/plattform/backend: backend().boerse(null, filter) -> { projekte, demo }).
 * Fehlt das Backend, ist es nicht konfiguriert (HTTP 503) oder antwortet es
 * nicht, bleibt die Sitemap trotzdem vollständig – nur ohne Projektseiten.
 * Demo-Daten landen bewusst nie in der Sitemap.
 */
async function projektEintraege() {
  try {
    const modul = await import("@/lib/plattform/backend");
    const impl = typeof modul.backend === "function" ? modul.backend() : modul;
    if (typeof impl?.boerse !== "function") return [];
    const antwort = await Promise.race([
      impl.boerse(null, {}),
      new Promise((_, nein) => setTimeout(() => nein(new Error("Zeitüberschreitung")), 5000)),
    ]);
    if (antwort?.demo) return [];
    const liste = Array.isArray(antwort) ? antwort : antwort?.projekte || [];
    return liste
      .filter((p) => p && typeof p.slug === "string" && /^[a-z0-9-]+$/.test(p.slug))
      .map((p) => {
        const d = new Date(p.geaendertAm || p.aktualisiert || p.veroeffentlichtAm || p.modified || START);
        return {
          url: abs(`/projektboerse/${p.slug}`),
          lastModified: Number.isNaN(d.getTime()) ? START : d,
          changeFrequency: "weekly",
          priority: 0.6,
        };
      });
  } catch {
    return [];
  }
}

export default async function sitemap() {
  const seiten = SEITEN.map(({ pfad, prio, freq, datum }) => ({
    url: abs(pfad),
    lastModified: datum || START,
    changeFrequency: freq,
    priority: prio,
  }));

  const ratgeber = alleArtikel().map((a) => ({
    url: abs(artikelPfad(a.slug)),
    lastModified: new Date(a.aktualisiert),
    changeFrequency: "monthly",
    priority: 0.7,
  }));

  const projekte = await projektEintraege();

  const regionen = [
    { url: abs("/regionen"), lastModified: START, changeFrequency: "monthly", priority: 0.8 },
    ...REGIONEN_META.map((r) => ({ url: abs(`/regionen/${r.slug}`), lastModified: START, changeFrequency: "monthly", priority: 0.8 })),
  ];

  return [...seiten, ...regionen, ...ratgeber, ...projekte];
}
// src/app/robots.js – robots.txt der ÖkoInvest-Website
//
// Öffentliche Seiten sind frei. Portal und API werden nicht gecrawlt
// (personenbezogene bzw. vertrauliche Inhalte, Anmeldung erforderlich).
//
// Anmeldung, Registrierung, Passwort-Reset, Einladungen, Angebote mit Code,
// Terminverwaltung, Styleguide und Entwürfe sind bewusst NICHT gesperrt: Sie
// tragen <meta name="robots" content="noindex">, und Suchmaschinen müssen die
// Seite abrufen dürfen, um das noindex zu sehen. Eine Sperre hier würde dazu
// führen, dass verlinkte URLs (z. B. /login im Footer) ohne Inhalt im Index
// landen.
//
// KI-Trainingscrawler ohne Nutzen für Suche und Antworten werden gesperrt.
// KI-Such- und Antwortcrawler (OAI-SearchBot, ChatGPT-User, PerplexityBot,
// Claude-SearchBot, Bingbot, Googlebot inkl. AI Overviews) bleiben erlaubt.
//
// Domain kommt aus SITE.url (NEXT_PUBLIC_SITE_URL) – kein fester Hostname.

import { SITE } from "@/data/site";

export default function robots() {
  return {
    rules: [
      {
        userAgent: "*",
        allow: ["/", "/_next/image"],
        disallow: ["/api/", "/portal"],
      },
      {
        userAgent: ["GPTBot", "CCBot", "Bytespider", "Google-Extended", "Meta-ExternalAgent", "cohere-ai"],
        disallow: "/",
      },
    ],
    sitemap: `${SITE.url}/sitemap.xml`,
  };
}

